# 1. For loop: print numbers

for (num in 1:50) {
  # Check if num is divisible by 3 or 5
  if (num %% 3 == 0 || num %% 5 == 0) {
    print(num)
  }
}



# 2. While loop: cumulative sum

cum_sum &lt;- 0  # cumulative sum starts at 0
i &lt;- 1        # start at number 1

while (cum_sum &lt;= 200 && i &lt;= 50) {
  if (i %% 3 == 0 || i %% 5 == 0) {
    cum_sum &lt;- cum_sum + i
  }

  i &lt;- i + 1  # go to the next number
}

